#!/usr/bin/env python3
# Generated by `verdant-studio publish` from studio/src/Studio/Ops.lex.tex. Do not edit.
# Studio.Agent.Interface.Resource (REQ-UI-PRISM, REQ-AGENT-INTERFACE): the view tree of the Studio UI Prism, published
# as MCP resources. Each journey's routes, views and actions are read from the app's own acceptance vectors, the
# answers its model gives, and its guards from the build rows of its suite in model/ids.toml, so nothing here
# restates the model. The resource list must be a ListResourcesResult, and each journey a ReadResourceResult, of
# the bound MCP-SCHEMA-2026-07-28. gui-tree.py COMMAND... runs COMMAND record on the app's holo.
import glob, json, subprocess, sys, tomllib
SLASH = chr(47)
TYPES = {'object': dict, 'array': list, 'string': str, 'boolean': bool, 'null': type(None)}
schema = json.load(open(SLASH.join(['authorities', 'MCP-SCHEMA-2026-07-28', 'schema.json'])))
defs = schema['$defs']

def numeric(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)

def check(value, rule, where, problems):
    if not isinstance(rule, dict):
        return
    if '$ref' in rule:
        check(value, defs[rule['$ref'].split(SLASH)[-1]], where, problems)
    kinds = rule.get('type')
    if kinds is not None:
        kinds = kinds if isinstance(kinds, list) else [kinds]
        fits = any((kind in ('number', 'integer') and numeric(value)) or (kind in TYPES and isinstance(value, TYPES[kind])) for kind in kinds)
        if not fits:
            problems.append(where + ' is not of type ' + repr(kinds))
            return
    if 'enum' in rule and value not in rule['enum']:
        problems.append(where + ' is not one of ' + repr(rule['enum']))
    if 'const' in rule and value != rule['const']:
        problems.append(where + ' is not ' + repr(rule['const']))
    if isinstance(value, dict):
        for name in rule.get('required', []):
            if name not in value:
                problems.append(where + ' lacks ' + name)
        known = rule.get('properties', {})
        for name, item in value.items():
            if name in known:
                check(item, known[name], where + '.' + name, problems)
            elif rule.get('additionalProperties') is False:
                problems.append(where + ' has ' + name + ', which the schema does not allow')
            else:
                check(item, rule.get('additionalProperties'), where + '.' + name, problems)
    if isinstance(value, list) and 'items' in rule:
        for index, item in enumerate(value):
            check(item, rule['items'], where + '[' + str(index) + ']', problems)

holo = sorted(glob.glob(SLASH.join(['app', '.prism', 'build', '*.holo'])))[0]
record = SLASH.join(['target', 'gui-record.json'])
subprocess.run(sys.argv[1:] + ['record', holo, '--output', record], check=True, capture_output=True)
events = json.load(open(record))['events']
rows = tomllib.load(open(SLASH.join(['model', 'ids.toml']), 'rb'))['id']
prefix = 'studio' + chr(9) + 'gui' + chr(9)
journeys = {}
for event in events:
    request = bytes.fromhex(event['request']).decode('utf-8', 'replace')
    if not request.startswith(prefix):
        continue
    route = request[len(prefix):].split(chr(9))[0]
    entry = journeys.setdefault(route, {'route': prefix + route + chr(9), 'views': [], 'actions': {}})
    for line in bytes.fromhex(event['response']).decode('utf-8', 'replace').split(chr(10)):
        kind, _, rest = line.partition(' ')
        name, _, text = rest.partition(': ')
        if kind == 'journey':
            entry['journey'] = name
            entry['title'] = text
        elif kind == 'view' and name not in entry['views']:
            entry['views'].append(name)
        elif kind == 'action':
            states = entry['actions'].setdefault(name, [])
            state = text.split(',')[0]
            if state not in states:
                states.append(state)
problems = []
resources = []
reads = {}
for route, entry in sorted(journeys.items()):
    suite = 'gui-' + route
    rules = [{'id': row['id'], 'statement': row['statement']} for row in rows if row.get('suite') == suite and row.get('level') == 'build']
    journey = entry.get('journey', route)
    tree = {'journey': journey, 'title': entry.get('title', ''), 'route': entry['route'], 'views': entry['views'],
            'actions': [{'name': name, 'states': sorted(states)} for name, states in entry['actions'].items()], 'rules': rules}
    if not tree['views'] or not tree['actions'] or not rules:
        problems.append(journey + ' needs a view, an action and a build rule of suite ' + suite)
    uri = 'verdant-studio:' + SLASH + SLASH + 'gui' + SLASH + journey
    resources.append({'uri': uri, 'name': journey, 'title': tree['title'], 'mimeType': 'application' + SLASH + 'json',
                      'description': 'The ' + journey + ' journey of the Studio UI Prism: its route, views, actions and guards'})
    reads[journey] = {'cacheScope': 'public', 'resultType': 'complete', 'ttlMs': 0,
                      'contents': [{'uri': uri, 'mimeType': 'application' + SLASH + 'json', 'text': json.dumps(tree, sort_keys=True)}]}
listing = {'cacheScope': 'public', 'resultType': 'complete', 'ttlMs': 0, 'resources': resources}
check(listing, defs['ListResourcesResult'], 'resources-list', problems)
for journey, read in reads.items():
    check(read, defs['ReadResourceResult'], 'resources-read ' + journey, problems)
if not resources:
    problems.append('the app answers no journey of the Studio UI Prism')
for problem in problems:
    print('::error::the GUI view tree ' + problem)
if problems:
    sys.exit(1)
site = SLASH.join(['app', '.prism', 'site', 'surface'])
subprocess.run(['mkdir', '-p', site + SLASH + 'gui'], check=True)
json.dump(listing, open(site + SLASH + 'mcp-resources.json', 'w'), sort_keys=True)
for journey, read in reads.items():
    json.dump(read, open(site + SLASH + 'gui' + SLASH + journey + '.json', 'w'), sort_keys=True)
subprocess.run(['cp', SLASH.join(['surface', 'mcp-tools.json']), site], check=True)
print('accepted: ' + str(len(resources)) + ' journeys of the Studio UI Prism as MCP resources, valid against MCP-SCHEMA-2026-07-28: ' + ', '.join(sorted(reads)))
